import { useState, useRef, useEffect } from "react";
import { Link } from "react-router-dom";
import { Bell, ChevronDown, User, Settings, LogOut, CheckCircle2 } from "lucide-react";
import { useAuth } from "../auth";

function useClickOutside(ref, onOutside) {
  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) onOutside();
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [ref, onOutside]);
}

function TopBar() {
  const { user, logout } = useAuth();
  const [notifOpen, setNotifOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const notifRef = useRef(null);
  const profileRef = useRef(null);

  useClickOutside(notifRef, () => setNotifOpen(false));
  useClickOutside(profileRef, () => setProfileOpen(false));

  const today = new Date()
    .toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })
    .toUpperCase();

  const itemClass = "flex items-center gap-3 px-3 py-2.5 rounded-xl text-slate-700 hover:bg-slate-100 transition-colors";

  return (
    <header className="relative z-20 shrink-0 flex items-center justify-between px-14 h-24 bg-cream border-b border-slate-200">
      <p className="font-mono text-sm tracking-widest text-slate-500">{today}</p>

      <div className="flex items-center gap-6">
        <div ref={notifRef} className="relative">
          <button
            onClick={() => {
              setNotifOpen(!notifOpen);
              setProfileOpen(false);
            }}
            className="text-slate-600 hover:text-ink transition-colors"
            aria-label="Notifications"
          >
            <Bell size={24} strokeWidth={1.8} />
          </button>

          {notifOpen && (
            <div className="absolute right-0 mt-4 w-80 rounded-2xl bg-white border border-slate-200 shadow-xl overflow-hidden">
              <div className="px-5 py-4 border-b border-slate-100">
                <p className="font-semibold">Notifications</p>
              </div>
              <div className="flex flex-col items-center text-center px-6 py-10">
                <div className="w-14 h-14 rounded-full bg-mint text-money flex items-center justify-center">
                  <CheckCircle2 size={28} />
                </div>
                <p className="mt-4 font-semibold text-lg">You're all caught up</p>
                <p className="mt-1 text-sm text-slate-500">No new notifications right now.</p>
              </div>
            </div>
          )}
        </div>

        <div ref={profileRef} className="relative">
          <button
            onClick={() => {
              setProfileOpen(!profileOpen);
              setNotifOpen(false);
            }}
            className="flex items-center gap-3"
          >
            <span className="w-10 h-10 rounded-full bg-brand/20 text-brand text-sm font-semibold flex items-center justify-center">
              {user.initials}
            </span>
            <span className="font-semibold">{user.name.split(" ")[0]}</span>
            <ChevronDown size={16} className={`text-slate-500 transition-transform ${profileOpen ? "rotate-180" : ""}`} />
          </button>

          {profileOpen && (
            <div className="absolute right-0 mt-4 w-60 rounded-2xl bg-white border border-slate-200 shadow-xl overflow-hidden">
              <div className="px-5 py-4 border-b border-slate-100">
                <p className="font-semibold">{user.name}</p>
                <p className="text-sm text-slate-500 truncate">{user.email}</p>
              </div>
              <div className="p-2">
                <Link to="/profile" onClick={() => setProfileOpen(false)} className={itemClass}>
                  <User size={18} /> My profile
                </Link>
                <Link to="/settings" onClick={() => setProfileOpen(false)} className={itemClass}>
                  <Settings size={18} /> Settings
                </Link>
              </div>
              <div className="p-2 border-t border-slate-100">
                <button
                  onClick={logout}
                  className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-rose hover:bg-rose/10 transition-colors"
                >
                  <LogOut size={18} /> Log out
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

export default TopBar;
